Widget build(BuildContext context) {
    const etapas = [
      SituacaoPedido.aguardando,
      SituacaoPedido.aceito,
      SituacaoPedido.entregue,
    ];
    final atual = etapas.indexOf(situacao);
    final duracao = MovimentoDiskGas.duracao(context, MovimentoDiskGas.lento);
    Color corDoTraco(bool visivel, bool feito) => !visivel
        ? Colors.transparent
        : feito
        ? CoresDiskGas.laranjaEscuro
        : CoresDiskGas.areia;
    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        for (var i = 0; i < etapas.length; i++)
          Expanded(
            child: Column(
              children: [
                Row(
                  children: [
                    Expanded(
                      child: AnimatedContainer(
                        duration: duracao,
                        height: 3,
                        color: corDoTraco(i > 0, i <= atual),
                      ),
                    ),
                    AnimatedContainer(
                      duration: duracao,
                      width: 18,
                      height: 18,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        color: i <= atual
                            ? CoresDiskGas.laranjaEscuro
                            : Colors.white,
                        border: Border.all(
                          color: i <= atual
                              ? CoresDiskGas.laranjaEscuro
                              : CoresDiskGas.bordaCampo,
                          width: 2,
                        ),
                      ),
                    ),
                    Expanded(
                      child: AnimatedContainer(
                        duration: duracao,
                        height: 3,
                        color: corDoTraco(i < etapas.length - 1, i < atual),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 6),
                Text(
                  etapas[i].rotulo,
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    fontSize: 14,
                    fontWeight: i == atual ? FontWeight.w700 : FontWeight.w400,
                    color: i <= atual
                        ? CoresDiskGas.carvao
                        : CoresDiskGas.cinzaQuente,
                  ),
                ),
              ],
            ),
          ),
      ],
    );
  }

