  ) {
    final livre = !viewModel.processando;
    return switch (pedido.situacao) {
      SituacaoPedido.aguardando => [
        FilledButton(
          onPressed: livre
              ? () => _abrirDialogo(
                  context,
                  viewModel,
                  DialogoTexto(
                    titulo: 'Aceitar pedido',
                    rotulo: 'Tempo estimado (min)',
                    confirmar: 'Aceitar',
                    numerico: true,
                    acao: (tempo) async {
                      final aceito = await viewModel.aceitar(tempo);
                      if (aceito) HapticFeedback.mediumImpact();
                      return aceito;
                    },
                  ),
                )
              : null,
          child: const Text('Aceitar'),
        ),
        const SizedBox(height: 12),
